package io.invenlio.procurement;
import io.invenlio.organization.*;import java.sql.*;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service class ProcurementChildQueryService{private final AuthorizationService auth;private final JdbcTemplate db;ProcurementChildQueryService(AuthorizationService a,JdbcTemplate d){auth=a;db=d;}
 @Transactional(readOnly=true)List<ProcurementService.Address>addresses(UUID supplier,int page,int size){var a=access();bounds(page,size);owner(a.tenantId(),supplier);return db.query("SELECT id,supplier_id,type,label,address_line1,address_line2,postal_code,city,state_region,country_code,is_primary,status,created_at,updated_at,version FROM supplier_addresses WHERE tenant_id=? AND supplier_id=? ORDER BY type,is_primary DESC,id OFFSET ? LIMIT ?",this::addressRow,a.tenantId(),supplier,page*size,size);}
 @Transactional(readOnly=true)ProcurementService.Address address(UUID id){var a=access();var rows=db.query("SELECT id,supplier_id,type,label,address_line1,address_line2,postal_code,city,state_region,country_code,is_primary,status,created_at,updated_at,version FROM supplier_addresses WHERE tenant_id=? AND id=?",this::addressRow,a.tenantId(),id);if(rows.isEmpty())throw new ProcurementException("SUPPLIER_ADDRESS_NOT_FOUND","Supplier address not found");return rows.getFirst();}
 @Transactional(readOnly=true)List<ProcurementService.Contact>contacts(UUID supplier,int page,int size){var a=access();bounds(page,size);owner(a.tenantId(),supplier);return db.query("SELECT id,supplier_id,first_name,last_name,job_title,email,phone,role,is_primary,active,created_at,updated_at,version FROM supplier_contacts WHERE tenant_id=? AND supplier_id=? ORDER BY role,is_primary DESC,id OFFSET ? LIMIT ?",this::contactRow,a.tenantId(),supplier,page*size,size);}
 @Transactional(readOnly=true)ProcurementService.Contact contact(UUID id){var a=access();var rows=db.query("SELECT id,supplier_id,first_name,last_name,job_title,email,phone,role,is_primary,active,created_at,updated_at,version FROM supplier_contacts WHERE tenant_id=? AND id=?",this::contactRow,a.tenantId(),id);if(rows.isEmpty())throw new ProcurementException("SUPPLIER_CONTACT_NOT_FOUND","Supplier contact not found");return rows.getFirst();}
 private AuthorizationService.Access access(){return auth.require(Permission.PROCUREMENT_SUPPLIER_READ);}private void owner(UUID tenant,UUID id){if(db.queryForObject("SELECT count(*) FROM suppliers WHERE tenant_id=? AND id=?",Integer.class,tenant,id)==0)throw new ProcurementException("SUPPLIER_NOT_FOUND","Supplier not found");}private static void bounds(int p,int s){if(p<0||s<1||s>100)throw new ProcurementException("INVALID_PAGINATION","Invalid pagination");}private ProcurementService.Address addressRow(ResultSet r,int n)throws SQLException{return new ProcurementService.Address((UUID)r.getObject(1),(UUID)r.getObject(2),r.getString(3),r.getString(4),r.getString(5),r.getString(6),r.getString(7),r.getString(8),r.getString(9),r.getString(10),r.getBoolean(11),r.getString(12),r.getTimestamp(13).toInstant(),r.getTimestamp(14).toInstant(),r.getLong(15));}private ProcurementService.Contact contactRow(ResultSet r,int n)throws SQLException{return new ProcurementService.Contact((UUID)r.getObject(1),(UUID)r.getObject(2),r.getString(3),r.getString(4),r.getString(5),r.getString(6),r.getString(7),r.getString(8),r.getBoolean(9),r.getBoolean(10),r.getTimestamp(11).toInstant(),r.getTimestamp(12).toInstant(),r.getLong(13));}}
